def remove_grok_agents(apps, schema_editor):
    """Remove the Grok Agents that earlier builds created, with their connections and bot users.

    The Grok Harness is no longer offered. A left-over Agent would still hold its handle in the
    workspace, and its bot user would stay. The base managers include soft-deleted rows, and their
    querysets delete the rows from the table.
    """
    Agent = apps.get_model("db", "Agent")
    AgentConnection = apps.get_model("db", "AgentConnection")
    User = apps.get_model("db", "User")
    agent_ids = list(Agent._base_manager.filter(harness="grok").values_list("id", flat=True))
    bot_user_ids = list(Agent._base_manager.filter(id__in=agent_ids).values_list("bot_user_id", flat=True))
    AgentConnection._base_manager.filter(agent_id__in=agent_ids).delete()
    Agent._base_manager.filter(id__in=agent_ids).delete()
    User._base_manager.filter(id__in=bot_user_ids, is_bot=True).delete()


